const now = Date.now();
const seen = new Set();
const KEYWORDS = ['business','enterprise','roi','automation','retail','llm','agent','vision','detection','deploy','production','case study','customer','cost','revenue'];
let out = [];
for (const it of items) {
  const j = it.json;
  const link = j.link || j.guid;
  if (!link || seen.has(link)) continue;
  seen.add(link);
  const d = new Date(j.pubDate || j.isoDate || 0).getTime();
  const maxAge = j.isResearch ? 1000 * 60 * 60 * 24 * 30 : 1000 * 60 * 60 * 24;
  if (!d || now - d > maxAge) continue;
  const txt = ((j.title || '') + ' ' + (j.contentSnippet || j.content || '')).toLowerCase();
  const score = KEYWORDS.reduce((s, k) => s + (txt.includes(k) ? 1 : 0), 0) + (/ainewsbot\.(tech|vision)/i.test(link) ? 10 : 0) + (j.isResearch ? 3 : 0);
  out.push({ json: { title: j.title, link, content: (j.contentSnippet || j.content || '').slice(0, 1500), pubDate: j.pubDate, isResearch: !!j.isResearch, score } });
}
out.sort((a, b) => b.json.score - a.json.score);
return out.slice(0, 2);

const src = $('Дедуплікація').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const html = items[i].json.data || '';
  let img = null;
  const m = html.match(/property=["']og:image["'][^>]*content=["']([^"']+)["']/i) || html.match(/content=["']([^"']+)["'][^>]*property=["']og:image["']/i);
  if (m && !/logo|favicon/i.test(m[1])) img = m[1];
  const orig = src[i] ? src[i].json : {};
  out.push({ json: { title: orig.title, link: orig.link, content: orig.content, imageUrl: img } });
}
return out;

